  GLOSSARY = [
    [7, "About the Deck", ["The Deck is the pile of cards", "you will be drawing from.", "At the beginning of your turn, you", "will draw 1 card from your Deck.", "If there are no cards to draw", "from the Deck, you lose the game."]],
    [5, "About the Discard Pile", ["The pile in which you place used", "cards is called the Discard Pile.", "You can look at both yours and your", "opponent's Discard Pile ", "with the Check command."]],
    [7, "About the Hand", ["The cards held by each player", "are called a Hand.", "There is no restriction to the", "number of cards in the Hand.", "You may even have 10 or 20 ", "cards in your Hand."]],
    [6, "About the Arena", ["The place where the Pokémon", "that is actively fighting", "is placed is called the Arena.", "The game proceeds by using the", "Active Pokémon in the Arena."]],
    [6, "About the Bench", ["The Bench is where your Pokémon", "that are in play but aren't actively", "fighting sit.", "They're ready to come out and fight", "if the Active Pokémon retreats or", "is Knocked Out.", "You can have up to 5 Pokémon on", "the Bench."]],
    [4, "About the Active Pokémon", ["The Active Pokémon is the ", "Pokémon that is in the Arena.", "Only Active Pokémon can ", "attack."]],
    [5, "About Bench Pokémon", ["The Pokémon that are in play", "but aren't actively fighting", "are called Bench Pokémon.", "They're ready to come out and fight", "if the Active Pokémon retreats or", "is Knocked Out.", "If the Active Pokémon is Knocked", "Out and you don't have a Bench ", "Pokémon, you lose the game."]],
    [7, "About Prizes", ["Prizes are the cards placed to", "count the number of the opponent's", "Pokémon you Knocked Out.", "Every time one of your opponent's", "Pokémon is Knocked Out, you take 1", "of your Prizes into your Hand.", "When you take all of your Prizes,", "you win the game."]],
    [5, "About Damage Counters", ["A Damage Counter represents the", "amount of damage a certain Pokémon", "has taken.", "1 Damage Counter represents", "10 HP of damage.", "If a Pokémon with an HP of 30 has", "3 Damage Counters, it has received", "30 HP of damage, and its remaining", "HP is 0."]],
    [5, "About Energy Cards", ["Energy Cards are cards that power", "your Pokémon, making them able", "to Attack.", "There are 7 types of Energy Cards", "[<GRASS> Grass] [<FIRE> Fire]", "[<WATER> Water] [<LIGHTNING> Lightning]", "[<PSYCHIC> Psychic] [<FIGHTING> Fighting]", "and [<COLORLESS> Double Colorless]", "You may only play 1 Energy Card", "from your Hand per turn."]],
    [5, "About Trainer Cards", ["Trainer Cards are support cards.", "There are many Trainer Cards", "with different effects.", "Trainer Cards are played during", "your turn by following the", "instructions on the card and then", "discarding it.", "You may use as many Trainer Cards", "as you like."]],
    [5, "About Basic Pokémon", ["Basic Pokémon are cards that ", "can be played directly from your ", "hand into the play area. Basic ", "Pokémon act as the base for ", "Evolution Cards. Charmander, ", "Squirtle and Bulbasaur are", "examples of Basic Pokémon."]],
    [5, "About Evolution Cards", ["Evolution Cards are cards you", "play on top of a Basic Pokémon card", "(or sometimes on top of another", "Evolution Card) to make it stronger.", "There are Stage 1 and Stage 2", "Evolution Cards.", "If you do not have a Basic Pokémon", "in the Play Area, you cannot place", "the Stage 1 Evolution Card, and if", "you do not have a Stage 1 Evolution", "Card in the Play Area, you cannot", "place the Stage 2 Evolution Card."]],
    [6, "About Attacking", ["By choosing Attack, your Pokémon", "will fight your opponent's Pokémon.", "Your Pokémon require Energy", "in order to Attack.", "The amount of Energy required", "differs according to the Attack.", "The Active Pokémon is the only", "Pokémon that can Attack."]],
    [5, "About Pokémon Power", ["Unlike Attacks, Pokémon Power", "can be used by Active or Benched", "Pokémon. Some Pokémon Power are", "effective by just placing the", "Pokémon in the Play Area, but for", "some you must choose the", "command, PKMN Power."]],
